-- Root entity custom CSS state before watermark/apply-watermark.php ran.
UPDATE glpi_entities SET enable_custom_css = 1, custom_css_code = '/*
 * ITSM logo override. Replaces GLPI\'s stock logo everywhere it renders
 * via CSS custom properties (--glpi-logo*) that .glpi-logo already
 * reads from — see css/includes/_base.scss. No core files touched;
 * applied through Entity > Custom CSS (root entity), same mechanism as
 * topbar-modern.css.
 *
 * v3 design (squircle badge, 3-stop gradient, status dot, black-weight
 * wordmark + underline bar). v4: much bigger login hero + wider topbar
 * mark, per feedback that v2\'s sizing still read too small.
 *
 * Source SVGs: logo/icon.svg, logo/lockup-light-text.svg,
 * logo/lockup-dark-text.svg (see logo/README.md).
 */

:root {
    --glpi-logo-light: url("data:image/svg+xml;base64,") !important;
    --glpi-logo-dark: url("data:image/svg+xml;base64,") !important;
    --glpi-logo-light-reduced: url("data:image/svg+xml;base64,") !important;
    --glpi-logo-dark-reduced: url("data:image/svg+xml;base64,") !important;
    --glpi-logo-dark-login: url("data:image/svg+xml;base64,") !important;
    --glpi-logo-light-login: url("data:image/svg+xml;base64,") !important;
}

.glpi-logo {
    background-size: contain !important;
    background-position: center !important;
}

/* Login page hero: big, confident presence. */
body.welcome-anonymous .glpi-logo {
    width: 560px !important;
    height: 147px !important;
    max-width: 90vw;
    filter: drop-shadow(0 14px 32px rgba(37, 99, 235, 0.28));
}

/* Topbar: wider mark, still within the nav bar\'s height. */
.topbar .glpi-logo {
    width: 150px !important;
    height: 54px !important;
}
' WHERE id = 0;
